#include <iostream>
using namespace std;

int clamp(int val, int lo, int hi) {
    if (val < lo) return lo;
    if (val > hi) return hi;
    return val;
}

int diff(int a, int b) {
    if (a >= b) return a - b;
    return b - a;
}

int main() {
    int v, lo, hi, a, b;
    cin >> v >> lo >> hi >> a >> b;

    cout << "CLAMPED: " << clamp(v, lo, hi) << endl;
    cout << "DIFF: " << diff(a, b) << endl;

    return 0;
}

