#include <iostream>
#include <vector>
using namespace std;

int compute_sum(const vector<int> &v) {
    int total = 0;
    for (int i = 0; i < v.size(); i++) {
        total += v[i];
    }
    return total;
}

int find_min(const vector<int> &v) {
    int m = v[0];
    for (int i = 1; i < v.size(); i++) {
        if (v[i] < m) {
            m = v[i];
        }
    }
    return m;
}

int main() {
    int count;
    cin >> count;

    vector<int> data;
    for (int i = 0; i < count; i++) {
        int x;
        cin >> x;
        data.push_back(x);
    }

    cout << "SUM: " << compute_sum(data) << endl;
    cout << "MIN: " << find_min(data) << endl;

    return 0;
}

